/* Fixed C++ pointer/lifetime projection over the bound concrete memory model. */
#include <cstdint>
#include <climits>
#include <initializer_list>
#include <type_traits>
static_assert(CHAR_BIT==8 && sizeof(int)==4 && sizeof(void*)==8,"runtime-source-ABI");
#if !defined(__BYTE_ORDER__) || __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error unsupported_runtime_source_byte_order
#endif
enum class Operation_t {
    ADD_OP = 0,
    SUB_OP = 1,
    MUL_OP = 2,
    DIV_OP = 3,
    MIN_OP = 4,
    MAX_OP = 5,
    AND_OP = 6,
    OR_OP = 7,
    XOR_OP = 8,
    SHL_OP = 9,
    SHR_OP = 10,
    GT_OP = 11,
    GTE_OP = 12,
    LT_OP = 13,
    LTE_OP = 14,
    EQ_OP = 15,
    NE_OP = 16,
    MAX
};
enum OpcodeType : uint8_t {
    STREAM_LD = 0,
    STREAM_ST = 1,
    INDIR_LD = 2,
    INDIR_ST_SCALAR = 3,
    INDIR_ST_VECTOR = 4,
    INDIR_RMW_SCALAR = 5,
    INDIR_RMW_VECTOR = 6,
    RANGE_LOOP = 7,
    ALU_SCALAR = 8,
    ALU_VECTOR = 9,
    ALU_REDUCE = 10
};
enum class DataType : uint8_t {
    UINT32_TYPE = 0,
    INT32_TYPE = 1,
    FLOAT32_TYPE = 2,
    UINT64_TYPE = 3,
    INT64_TYPE = 4,
    FLOAT64_TYPE = 5,
    MAX
};
static constexpr unsigned dws_cxx_thread = 0u;
static void dws_cxx_enter(unsigned object) {switch(object) {case 0:dws_local_enter_0_v1();break;case 1:dws_local_enter_1_v1();break; default:SWDB_CHECK(0,"runtime-allocation-object");}}
static void dws_cxx_leave(unsigned object) {switch(object) {case 0:dws_local_leave_0_v1();break;case 1:dws_local_leave_1_v1();break; default:SWDB_CHECK(0,"runtime-allocation-object");}}
static dws_pointer dws_cxx_live(dws_pointer p) {
  if(p.kind==1) dws_local_require_v1(p.object,dws_cxx_thread);
  (void)dws_pointer_bytes(p);return p;
}
struct dws_cxx_erased {
  dws_pointer value;
  explicit dws_cxx_erased(dws_pointer p):value(dws_cxx_live(p)) {}
  dws_pointer get() const {return dws_cxx_live(value);}
};
template<class T> struct dws_cxx_traits;
template<> struct dws_cxx_traits<uint32_t> {static constexpr unsigned dtype=0u;static_assert(sizeof(uint32_t)==4 && alignof(uint32_t)==4,"runtime-scalar-ABI");static uint32_t load(dws_pointer p) {return dws_cpu_load_u32(dws_cxx_thread,p,0);}static void store(dws_pointer p,uint32_t v) {dws_cpu_store_u32(dws_cxx_thread,p,0,v);}};
template<> struct dws_cxx_traits<int32_t> {static constexpr unsigned dtype=1u;static_assert(sizeof(int32_t)==4 && alignof(int32_t)==4,"runtime-scalar-ABI");static int32_t load(dws_pointer p) {return dws_cpu_load_i32(dws_cxx_thread,p,0);}static void store(dws_pointer p,int32_t v) {dws_cpu_store_i32(dws_cxx_thread,p,0,v);}};
template<> struct dws_cxx_traits<float> {static constexpr unsigned dtype=2u;static_assert(sizeof(float)==4 && alignof(float)==4,"runtime-scalar-ABI");static float load(dws_pointer p) {return dws_cpu_load_f32(dws_cxx_thread,p,0);}static void store(dws_pointer p,float v) {dws_cpu_store_f32(dws_cxx_thread,p,0,v);}};
template<> struct dws_cxx_traits<uint64_t> {static constexpr unsigned dtype=3u;static_assert(sizeof(uint64_t)==8 && alignof(uint64_t)==8,"runtime-scalar-ABI");static uint64_t load(dws_pointer p) {return dws_cpu_load_u64(dws_cxx_thread,p,0);}static void store(dws_pointer p,uint64_t v) {dws_cpu_store_u64(dws_cxx_thread,p,0,v);}};
template<> struct dws_cxx_traits<int64_t> {static constexpr unsigned dtype=4u;static_assert(sizeof(int64_t)==8 && alignof(int64_t)==8,"runtime-scalar-ABI");static int64_t load(dws_pointer p) {return dws_cpu_load_i64(dws_cxx_thread,p,0);}static void store(dws_pointer p,int64_t v) {dws_cpu_store_i64(dws_cxx_thread,p,0,v);}};
template<> struct dws_cxx_traits<double> {static constexpr unsigned dtype=5u;static_assert(sizeof(double)==8 && alignof(double)==8,"runtime-scalar-ABI");static double load(dws_pointer p) {return dws_cpu_load_f64(dws_cxx_thread,p,0);}static void store(dws_pointer p,double v) {dws_cpu_store_f64(dws_cxx_thread,p,0,v);}};
template<class T> struct dws_cxx_reference {
  dws_pointer value;
  explicit dws_cxx_reference(dws_pointer p):value(dws_cxx_live(p)) {}
  operator T() const {return dws_cxx_traits<T>::load(dws_cxx_live(value));}
  dws_cxx_reference& operator=(T v) {dws_cxx_traits<T>::store(dws_cxx_live(value),v);return *this;}
  /* First source scope writes scalar values only. A proxy RHS would postpone
     its CPU read until after LHS formation; refuse rather than change order. */
  dws_cxx_reference& operator=(const dws_cxx_reference&)=delete;
};
template<class T> struct dws_cxx_pointer {
  dws_pointer value;
  explicit dws_cxx_pointer(dws_pointer p):value(dws_cxx_live(p)) {SWDB_CHECK(p.dtype==dws_cxx_traits<T>::dtype,"runtime-pointer-type");}
  operator dws_cxx_erased() const {return dws_cxx_erased(dws_cxx_live(value));}
  dws_cxx_pointer operator+(long long n) const {return dws_cxx_pointer(dws_pointer_offset(dws_cxx_live(value),n));}
  dws_cxx_reference<T> operator[](long long n) const {return dws_cxx_reference<T>(dws_pointer_offset(dws_cxx_live(value),n));}
};
template<class T> struct dws_cxx_address {
  dws_pointer value;
  explicit dws_cxx_address(dws_pointer p):value(p) {SWDB_CHECK(p.kind==3 && p.dtype==dws_cxx_traits<T>::dtype,"runtime-address-only");}
};
template<class T,unsigned N,unsigned Object> struct dws_cxx_array {
  dws_pointer value;
  dws_cxx_array()=delete;
  dws_cxx_array(std::initializer_list<T> values):value(dws_object_pointer(Object)) {
    SWDB_CHECK(value.dtype==dws_cxx_traits<T>::dtype && dws_objects[Object].extent==N,"runtime-array-source-type");
    SWDB_CHECK(values.size()<=N,"runtime-array-initializer-domain");dws_cxx_enter(Object);
    unsigned i=0;for(T item:values)dws_cxx_traits<T>::store(dws_cxx_live(dws_pointer_offset(value,i++)),item);
    for(;i<N;++i)dws_cxx_traits<T>::store(dws_cxx_live(dws_pointer_offset(value,i)),T{});
  }
  dws_cxx_array(const dws_cxx_array&)=delete;
  dws_cxx_array& operator=(const dws_cxx_array&)=delete;
  ~dws_cxx_array() {dws_cxx_leave(Object);}
  operator dws_cxx_erased() const {return dws_cxx_erased(dws_cxx_live(value));}
  dws_cxx_pointer<T> operator+(long long n) const {return dws_cxx_pointer<T>(dws_pointer_offset(dws_cxx_live(value),n));}
  dws_cxx_reference<T> operator[](long long n) const {return dws_cxx_reference<T>(dws_pointer_offset(dws_cxx_live(value),n));}
};

